CREATE TABLE session_cleanup_completions ( namespace TEXT NOT NULL, session_name TEXT NOT NULL, session_uid TEXT NOT NULL DEFAULT '', operation_id TEXT NOT NULL, operation_digest TEXT NOT NULL, completed_at TIMESTAMP NOT NULL, PRIMARY KEY(namespace, session_name) );
CREATE TABLE session_cleanup_intents ( namespace TEXT NOT NULL, session_name TEXT NOT NULL, operation_id TEXT NOT NULL, operation_digest TEXT NOT NULL, plan BLOB NOT NULL, created_at TIMESTAMP NOT NULL, PRIMARY KEY(namespace, session_name) );
CREATE TABLE session_controls ( namespace TEXT NOT NULL, session_name TEXT NOT NULL, session_uid TEXT NOT NULL UNIQUE, request_digest TEXT NOT NULL, availability TEXT NOT NULL CHECK(availability IN ('Available','ReconciliationBlocked')), runtime_session_generation INTEGER NOT NULL DEFAULT 0 CHECK(runtime_session_generation >= 0), lease_generation INTEGER NOT NULL DEFAULT 0 CHECK(lease_generation >= 0), lease_task_uid TEXT NOT NULL DEFAULT '', lease_attempt INTEGER NOT NULL DEFAULT 0 CHECK(lease_attempt >= 0), lease_prompt_id TEXT NOT NULL DEFAULT '', lease_request_digest TEXT NOT NULL DEFAULT '', lease_acquired_at TIMESTAMP, lease_expires_at TIMESTAMP, blocked_reason TEXT NOT NULL DEFAULT '', related_prompt_attempt_id TEXT NOT NULL DEFAULT '', related_publication_id TEXT NOT NULL DEFAULT '', verified_repository_id TEXT NOT NULL DEFAULT '', verified_ref TEXT NOT NULL DEFAULT '', verified_sha TEXT NOT NULL DEFAULT '', controller_epoch_name TEXT NOT NULL, controller_epoch INTEGER NOT NULL CHECK(controller_epoch > 0), last_operation_id TEXT NOT NULL DEFAULT '', last_operation_digest TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL CHECK(version > 0), created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, PRIMARY KEY(namespace, session_name), FOREIGN KEY(namespace, session_name) REFERENCES sessions(namespace, name) ON DELETE RESTRICT, CHECK((lease_task_uid = '' AND lease_attempt = 0 AND lease_prompt_id = '' AND lease_request_digest = '' AND lease_acquired_at IS NULL AND lease_expires_at IS NULL) OR (lease_task_uid <> '' AND lease_attempt > 0 AND lease_prompt_id <> '' AND lease_request_digest <> '' AND lease_acquired_at IS NOT NULL)), CHECK((availability = 'Available' AND blocked_reason = '') OR availability = 'ReconciliationBlocked'), CHECK((verified_repository_id = '' AND verified_ref = '' AND verified_sha = '') OR (verified_repository_id <> '' AND verified_ref <> '' AND verified_sha <> '')) );
CREATE TABLE session_lineages ( namespace TEXT NOT NULL, session_name TEXT NOT NULL, namespace_uid TEXT NOT NULL, session_uid TEXT NOT NULL, contract_version TEXT NOT NULL CHECK(contract_version IN ('orka.harness.v1','orka.harness.v2')), lineage_generation INTEGER NOT NULL CHECK(lineage_generation > 0), runtime_identity TEXT NOT NULL, config_digest TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL CHECK(version > 0), created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, PRIMARY KEY (namespace, session_name), UNIQUE (session_uid) );
CREATE TABLE session_messages ( id INTEGER PRIMARY KEY AUTOINCREMENT, namespace TEXT NOT NULL, session_name TEXT NOT NULL, message_id TEXT NOT NULL DEFAULT '', sort_order INTEGER NOT NULL DEFAULT 0, role TEXT NOT NULL, content TEXT NOT NULL DEFAULT '', name TEXT, input TEXT, tool_calls TEXT, tool_call_id TEXT, source_type TEXT NOT NULL DEFAULT '', source_ref TEXT NOT NULL DEFAULT '', metadata_json TEXT NOT NULL DEFAULT '{}', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (namespace, session_name) REFERENCES sessions(namespace, name) ON DELETE CASCADE );
CREATE TABLE session_turn_cleanup_receipts ( turn_id TEXT PRIMARY KEY, prompt_attempt_id TEXT NOT NULL UNIQUE, namespace TEXT NOT NULL, session_name TEXT NOT NULL, session_uid TEXT NOT NULL, receipt_digest TEXT NOT NULL, receipt BLOB NOT NULL );
CREATE TABLE session_turns ( id TEXT PRIMARY KEY, namespace TEXT NOT NULL, session_name TEXT NOT NULL, session_uid TEXT NOT NULL, lease_generation INTEGER NOT NULL CHECK(lease_generation > 0), task_uid TEXT NOT NULL, attempt INTEGER NOT NULL CHECK(attempt > 0), prompt_id TEXT NOT NULL, prompt_attempt_id TEXT NOT NULL, request_digest TEXT NOT NULL, user_prompt TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('Open','Finalized')), terminal_kind TEXT NOT NULL DEFAULT '' CHECK(terminal_kind IN ('','AssistantResult','OutcomeMarker')), terminal_content TEXT NOT NULL DEFAULT '', finalization_digest TEXT NOT NULL DEFAULT '', publication_id TEXT NOT NULL DEFAULT '', publication_receipt BLOB, projection_id TEXT NOT NULL DEFAULT '', projection_kind TEXT NOT NULL DEFAULT '', projection_digest TEXT NOT NULL DEFAULT '', projection_available_at TIMESTAMP, controller_epoch_name TEXT NOT NULL, controller_epoch INTEGER NOT NULL CHECK(controller_epoch > 0), version INTEGER NOT NULL CHECK(version > 0), created_at TIMESTAMP NOT NULL, finalized_at TIMESTAMP, updated_at TIMESTAMP NOT NULL, UNIQUE(session_uid, lease_generation, task_uid, attempt, prompt_id), FOREIGN KEY(namespace, session_name) REFERENCES sessions(namespace, name) ON DELETE RESTRICT, CHECK((state = 'Open' AND terminal_kind = '' AND finalization_digest = '' AND finalized_at IS NULL) OR (state = 'Finalized' AND terminal_kind <> '' AND finalization_digest <> '' AND finalized_at IS NOT NULL)) );
CREATE TABLE sessions ( namespace TEXT NOT NULL, name TEXT NOT NULL, session_type TEXT NOT NULL DEFAULT 'task', owner_type TEXT NOT NULL DEFAULT '', owner_ref TEXT NOT NULL DEFAULT '', active_task TEXT NOT NULL DEFAULT '', active_task_uid TEXT NOT NULL DEFAULT '', active_task_expires_at TIMESTAMP, chat_turn_id TEXT NOT NULL DEFAULT '', chat_turn_expires_at TIMESTAMP, control_session_uid TEXT NOT NULL DEFAULT '', message_count INTEGER NOT NULL DEFAULT 0, input_tokens INTEGER NOT NULL DEFAULT 0, output_tokens INTEGER NOT NULL DEFAULT 0, cancelled BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (namespace, name) );
CREATE TABLE task_data_cleanup_generations ( namespace TEXT PRIMARY KEY, generation INTEGER NOT NULL );
CREATE TABLE task_data_task_generations ( namespace TEXT NOT NULL, task_name TEXT NOT NULL, generation INTEGER NOT NULL, PRIMARY KEY (namespace, task_name) );
CREATE TABLE task_job_revocations ( namespace TEXT NOT NULL, task_uid TEXT NOT NULL, job_uid TEXT NOT NULL, PRIMARY KEY (namespace, task_uid, job_uid) );
CREATE TABLE usage_observations ( recorded_seq INTEGER PRIMARY KEY AUTOINCREMENT, namespace TEXT NOT NULL, id TEXT NOT NULL, task_uid TEXT NOT NULL, counter_id TEXT NOT NULL, observed_at INTEGER NOT NULL, data TEXT NOT NULL, UNIQUE (namespace, id) );
CREATE TABLE usage_pr_links ( namespace TEXT NOT NULL, work_id TEXT NOT NULL, repository TEXT NOT NULL, number INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY (namespace, work_id, repository, number) );
CREATE TABLE usage_pull_requests ( namespace TEXT NOT NULL, namespace_uid TEXT NOT NULL, repository TEXT NOT NULL, number INTEGER NOT NULL, observed_at INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY (namespace, namespace_uid, repository, number, observed_at) );
CREATE TABLE usage_retention ( id INTEGER PRIMARY KEY CHECK (id = 1), retained_since INTEGER NOT NULL );
CREATE TABLE usage_tasks ( namespace TEXT NOT NULL, task_uid TEXT NOT NULL, task_name TEXT NOT NULL, started_at INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY (namespace, task_uid) );
CREATE TABLE usage_work_requests ( namespace TEXT NOT NULL, id TEXT NOT NULL, started_at INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY (namespace, id) );
CREATE TABLE work_actions ( id TEXT PRIMARY KEY, monitor_namespace TEXT NOT NULL, monitor_name TEXT NOT NULL, run_id TEXT NOT NULL DEFAULT '', command_event_id TEXT NOT NULL DEFAULT '', monitor_generation INTEGER NOT NULL DEFAULT 0, target_kind TEXT NOT NULL DEFAULT '', target_number INTEGER NOT NULL DEFAULT 0, target_sha TEXT NOT NULL DEFAULT '', target_snapshot_digest TEXT NOT NULL DEFAULT '', intent TEXT NOT NULL DEFAULT '', desired_action TEXT NOT NULL DEFAULT '', depends_on_action_id TEXT NOT NULL DEFAULT '', dedupe_key TEXT NOT NULL DEFAULT '', idempotency_key TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT '', phase TEXT NOT NULL DEFAULT '', attempt INTEGER NOT NULL DEFAULT 0, lease_owner TEXT NOT NULL DEFAULT '', lease_expires_at TIMESTAMP, task_name TEXT NOT NULL DEFAULT '', blocked_reason TEXT NOT NULL DEFAULT '', error TEXT NOT NULL DEFAULT '', artifact_ids TEXT NOT NULL DEFAULT '', payload_digest TEXT NOT NULL DEFAULT '', metadata_json TEXT NOT NULL DEFAULT '{}', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, completed_at TIMESTAMP );
